#include "emb_kernel.h"
extern "C" __global__ __aicore__ void emb_custom_fp32(GM_ADDR w,GM_ADDR idx,GM_ADDR off,GM_ADDR y,GM_ADDR t){
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe p;
    EmbKernel<float> k; k.Init(w,idx,off,y,t,&p); k.Process();
}
extern "C" void emb_do_fp32(uint32_t d,void* s,uint8_t* w,uint8_t* idx,uint8_t* off,uint8_t* y,uint8_t* t){
    emb_custom_fp32<<<d,nullptr,s>>>(w,idx,off,y,t);
}

