#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "emb_tiling.h"
extern "C" void emb_do_fp32(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
namespace emb_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_embedding_bag(const at::Tensor &w, const at::Tensor &idx, const at::Tensor &off, const std::string &mode) {
    TORCH_CHECK(w.dim()==2&&idx.dim()==1&&off.dim()==1,"shapes"); TORCH_CHECK(w.scalar_type()==at::kFloat,"fp32 only");
    TORCH_CHECK(mode=="mean","only mean supported");
    const auto M=static_cast<int32_t>(off.sizes()[0]-1), N=static_cast<int32_t>(w.sizes()[1]);
    auto idx32=idx.to(at::kInt).contiguous(); auto off32=off.to(at::kInt).contiguous();
    const int32_t mNum=(M+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor y=at::empty({M,N},w.options());
    at::Tensor tc=at::empty({static_cast<long>(sizeof(EmbKernelTiling))},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<EmbKernelTiling*>(tc.data_ptr());
    t->M=M; t->N=N; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    auto tn=tc.to(at::kPrivateUse1); auto stm=c10_npu::getCurrentNPUStream().stream(false);
    emb_do_fp32(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(w.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(idx32.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(off32.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(y);
}}
PYBIND11_MODULE(_emb_ext, m) { m.def("run_embedding_bag",&emb_ext::run_embedding_bag,""); }

