#pragma once
#ifndef EMB_KERNEL_H
#define EMB_KERNEL_H
#include "kernel_operator.h"
#include "kernel_common.h"
#include "emb_tiling.h"

template <typename T>
class EmbKernel {
public:
    __aicore__ inline void Init(GM_ADDR w, GM_ADDR idx, GM_ADDR off, GM_ADDR y, GM_ADDR tm, AscendC::TPipe *p) {
        CopyTiling(&t_, tm);
        wGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(w), t_.M * t_.N);
        idxGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(idx), t_.M);
        offGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(off), t_.M + 1);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), t_.M * t_.N);
        if ASCEND_IS_AIV { pipe_ = p; sr_ = t_.blockM / AscendC::GetSubBlockNum(); }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li=0; li<t_.tasksPerCore; ++li) {
                const int bx=ci*t_.tasksPerCore+li; if(bx>=BlockCount()) continue;
                for (int r=0; r<sr_; ++r) {
                    const int ri=bx*t_.blockM+si*sr_+r; if(ri<t_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (t_.M + t_.blockM - 1) / t_.blockM; }
    __aicore__ inline void ProcessRow(int32_t bag) {
        int32_t start=offGM_.GetValue(bag), end=offGM_.GetValue(bag+1), bs=end-start;
        if(bs<=0) return;
        float inv=1.0f/static_cast<float>(bs);
        for (int32_t j=0; j<t_.N; ++j) {
            float sum=0.0f;
            for (int32_t i=start; i<end; ++i) {
                int32_t id=idxGM_.GetValue(i);
                sum += static_cast<float>(wGM_.GetValue(id*t_.N+j));
            }
            yGM_.SetValue(bag*t_.N+j, static_cast<T>(sum*inv));
        }
    }
private:
    EmbKernelTiling t_{}; AscendC::TPipe *pipe_{}; int sr_{};
    AscendC::GlobalTensor<T> wGM_, yGM_;
    AscendC::GlobalTensor<int32_t> idxGM_, offGM_;
};
#endif

